// 금액은 객체마다, 생성 수는 클래스에서 함께 관리해요.
class Ticket {
    int amount;
    static int created = 0;
    Ticket(int initial) {
        amount = initial;
        created++;
    }
    // 클래스 이름으로 부르는 static 메서드예요.
    static int countCreated() {
        return created;
    }
}

class Main {
    public static void main(String[] args) {
        // 두 객체는 서로 다른 주문 금액을 담아요.
        Ticket a = new Ticket(1000);
        Ticket b = new Ticket(2000);
        System.out.println(a.amount);
        System.out.println(b.amount);
    }
}

