// 클래스 초기화와 객체 초기화를 출력으로 나눠 봐요.
class TraceTicket {
    // 클래스를 처음 쓸 때 한 번 실행하는 블록이에요.
    static {
        System.out.println("class");
    }
    // new 할 때마다 생성자보다 먼저 실행하는 블록이에요.
    {
        System.out.println("object");
    }
    TraceTicket() {
        System.out.println("constructor");
    }
}

class Main {
    public static void main(String[] args) {
        // 클래스를 처음 쓰기 전에 before를 출력해요.
        System.out.println("before");
        TraceTicket a = new TraceTicket();
        TraceTicket b = new TraceTicket();
    }
}

// 기준은 공유하고 주문 금액은 객체마다 보관해요.
class Ticket {
    static final int FREE_FROM = 10000;
    int amount;
    Ticket(int initial) {
        amount = initial;
    }
}

class Main {
    public static void main(String[] args) {
        // 두 주문을 같은 공유 기준에 비교해요.
        int initial = 10000;
        Ticket a = new Ticket(initial);
        Ticket b = new Ticket(15000);
        System.out.println(a.amount >= Ticket.FREE_FROM);
        System.out.println(b.amount >= Ticket.FREE_FROM);
    }
}

